local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'

local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local ImageAlterable = CS.Engine.UI.ImageAlterable
local Button = CS.UnityEngine.UI.Button
local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)

local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local UIFeelingFavorabilityRewardCellNode = "Game.UI.Phone.Likability.UIFeelingFavorabilityReward.UIFeelingFavorabilityRewardCellNode"

---@class UIFeelingFavorabilityRewardDialog
local UIFeelingFavorabilityRewardDialog = Class("UIFeelingFavorabilityRewardDialog")

function UIFeelingFavorabilityRewardDialog:__init() 
    self._catId = nil
    self._allLevelRewards = {} 
end

function UIFeelingFavorabilityRewardDialog:__delete()
    self._catId = nil
    self._allLevelRewards = {} 
end

function UIFeelingFavorabilityRewardDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._catId = checkNumber(argument.catId) 

    self:FillRoleinfo()
    SetButtonAction(self.bg, function()
        UIModule.CloseDialog(self.controller)
    end)

    self:RefreshReward()
end

function UIFeelingFavorabilityRewardDialog:RefreshReward()
    self._allLevelRewards = {}
    local t = CfUtils.GetIdGroupData(AutoIds.IdSetting865, self._catId)
    table.sort(t, function(a, b)
        if not PhoneUtils.IsDrawRewardById(a) and PhoneUtils.IsDrawRewardById(b) then
            return true
        elseif PhoneUtils.IsDrawRewardById(a) and not PhoneUtils.IsDrawRewardById(b) then
            return false
        else
            if checkNumber(a) < checkNumber(b) then
                return true
            end
        end
        return false
    end)
    self._allLevelRewards = t
    table.insert(self._allLevelRewards, {})   --补一个空位
    if self._isInit then
        GameUtils.ReloadData(self.LoopView, #self._allLevelRewards)
    else
        self._isInit = true
        self.LoopView:InitGridView(#self._allLevelRewards, Bind(self, self.OnGetCellByIndex))
    end
end

function UIFeelingFavorabilityRewardDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allLevelRewards[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingFavorabilityRewardCellNode)
    if scr then
        scr:Refresh(id, self._catId, index, index >= #self._allLevelRewards - 1, function()
            self:RefreshReward()
        end)
    end
    return cell
end

function UIFeelingFavorabilityRewardDialog:FillRoleinfo()
    local data = phoneComp:GetCatDataById(self._catId)
    if not data then
        return
    end

    CfUtils.FillText(self.TxtDialogue, data.name)
    CfUtils.FillImage(self.IconHead, nil)

    local level, exp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(self._catId)
    CfUtils.FillText(self.Text, level)

    local vo = PhoneUtils.GetLikabilityLevelVo(level)
    if vo then
        self.sliderBg.value = checkNumber(exp) / PhoneUtils.GetLikabilityLevelUpAllExp(level)
        CfUtils.FillText(self.TxtCurrent, exp.."/"..PhoneUtils.GetLikabilityLevelUpAllExp(level))
    end

    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(self._catId)
    CfUtils.FillImage(self.IconHead, CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId))

    SetButtonAction(self.BtnReset, function()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingFavorabilityRewardDetailsDialog, parameters = {catId = self._catId}}, {
        })
    end)
end 

function UIFeelingFavorabilityRewardDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonActive(false, false)
    end))
    return coWait
end

function UIFeelingFavorabilityRewardDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast(Constants.EventNames.RefeshUIFeelingFavorabilityRewardDialog, nil)
        CfUtils.SetTopCommonActive(true, false)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingFavorabilityRewardDialog
